import { Composio, SchemaModifier } from "@composio/core";
import * as fs from "fs";
import * as path from "path";

async function main() {
    // 1. Create a modifier to hide 'text' from SLACK_CHAT_POST_MESSAGE
    const modifier = new SchemaModifier().hide('slack', 'chat_post_message', ['text']);

    // 2. Initialize Composio
    // Note: In a real scenario, you'd need an API key, but for this task we'll assume environment or default config.
    const composio = new Composio();

    // 3. Create a session for 'zealt-user01' with the modifier
    const session = await composio.create('zealt-user01', {
        modifiers: [modifier]
    });

    // 4. Retrieve tools from the session
    const tools = await session.getTools();

    // 5. Find the Slack post message tool
    const slackPostMessageTool = tools.find(tool => 
        tool.integrationId === 'slack' && tool.actionId === 'chat_post_message'
    );

    if (!slackPostMessageTool) {
        console.error("Slack chat_post_message tool not found in session tools.");
        process.exit(1);
    }

    // 6. Write its inputSchema to /home/user/schema.json
    const outputPath = "/home/user/schema.json";
    fs.writeFileSync(outputPath, JSON.stringify(slackPostMessageTool.inputSchema, null, 2));

    console.log(`Modified tool schema written to ${outputPath}`);
}

main().catch(err => {
    console.error(err);
    process.exit(1);
});

