import { Composio } from "@composio/core";
import * as fs from "fs";

async function main() {
    // 1. Initialize Composio
    const composio = new Composio();

    // 2. Create a session for 'zealt-user01'
    // Using a transformation function to hide 'text' from Slack post message tool
    const session = await composio.create('zealt-user01', {
        modifySchema: (context) => {
            if (context.integrationId === 'slack' && context.actionId === 'chat_post_message') {
                const schema = context.toolSchema;
                if (schema.inputSchema && schema.inputSchema.properties) {
                    // Hide 'text' by removing it from properties
                    delete schema.inputSchema.properties['text'];
                    // Also remove from required if present
                    if (schema.inputSchema.required) {
                        schema.inputSchema.required = schema.inputSchema.required.filter((p: string) => p !== 'text');
                    }
                }
                return schema;
            }
            return context.toolSchema;
        }
    });

    // 3. Retrieve tools from the session
    // In newer versions, tools might be accessible via a different method or directly from the session object
    // Let's try to get tools. Based on the logs, session might have a way to list tools.
    // However, the instructions mentioned `session.getTools()`.
    // Let's see what's available on session.
    console.log("Session properties:", Object.keys(session));

    // @ts-ignore
    const tools = await session.getTools();

    // 4. Find the Slack post message tool
    const slackPostMessageTool = tools.find((tool: any) => 
        tool.integrationId === 'slack' && tool.actionId === 'chat_post_message'
    );

    if (!slackPostMessageTool) {
        console.error("Slack chat_post_message tool not found in session tools.");
        process.exit(1);
    }

    // 5. Write its inputSchema to /home/user/schema.json
    const outputPath = "/home/user/schema.json";
    fs.writeFileSync(outputPath, JSON.stringify(slackPostMessageTool.inputSchema, null, 2));

    console.log(`Modified tool schema written to ${outputPath}`);
}

main().catch(err => {
    console.error(err);
    process.exit(1);
});

